parameters.jsCode:
const token = String($json.query?.accept_token ?? '');

if (!token) {
  return [{ json: { ...$json, token_valid_structure: false, token_error: 'MISSING_ACCEPT_TOKEN' } }];
}

const parts = token.split('.');
if (parts.length !== 3) {
  return [{ json: { ...$json, token_valid_structure: false, token_error: 'INVALID_ACCEPT_TOKEN_FORMAT' } }];
}

const [leadId, expiryRaw, signature] = parts;
const expiry = Number(expiryRaw);
if (!leadId || !Number.isInteger(expiry) || !signature) {
  return [{ json: { ...$json, token_valid_structure: false, token_error: 'INVALID_ACCEPT_TOKEN_COMPONENTS' } }];
}

return [{
  json: {
    ...$json,
    token_valid_structure: true,
    accept_token_lead_id: leadId,
    accept_token_expires_at: expiry,
    accept_token_signature: signature
  }
}];

const crypto = require('crypto');

if (!$json.token_valid_structure) {
  return [{ json: { ...$json, token_verified: false, token_error: $json.token_error ?? 'INVALID_TOKEN_STRUCTURE' } }];
}

const secret = $env.PROPOSAL_ACCEPT_HMAC_SECRET;
if (!secret) { throw new Error('3.0.1.4: PROPOSAL_ACCEPT_HMAC_SECRET is not configured'); }

const leadId = String($json.accept_token_lead_id);
const expiresAt = Number($json.accept_token_expires_at);
const suppliedSignature = String($json.accept_token_signature);
const payload = `${leadId}.${expiresAt}`;
const expectedSignature = crypto.createHmac('sha256', secret).update(payload, 'utf8').digest('hex');

const signaturesMatch = suppliedSignature.length === expectedSignature.length &&
  crypto.timingSafeEqual(Buffer.from(suppliedSignature, 'utf8'), Buffer.from(expectedSignature, 'utf8'));

const now = Math.floor(Date.now() / 1000);
const notExpired = Number.isInteger(expiresAt) && expiresAt > now;

return [{
  json: {
    ...$json,
    token_verified: signaturesMatch && notExpired,
    token_error: signaturesMatch ? (notExpired ? null : 'ACCEPT_TOKEN_EXPIRED') : 'ACCEPT_TOKEN_SIGNATURE_INVALID'
  }
}];

const reason = $json.token_error || 'ACCEPT_TOKEN_REJECTED';
return [{
  json: {
    ok: false, accepted: false, status: 'REJECTED_SECURITY_VALIDATION',
    error_code: reason, message: 'Proposal acceptance link is invalid or expired.',
    lead_id: $json.accept_token_lead_id ?? null, rejected_at: new Date().toISOString()
  }
}];

